"""Provider-free adjudication of the Director Quality V3 final canary.

This runner consumes the immutable raw outputs captured by commit 9db8f9f and
replays them through the corrected runtime SourceRef contract.  It never calls
an LLM or mutates the original canary artifacts.
"""
from __future__ import annotations

import copy, hashlib, json, re, sys
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
ARTIFACTS = ROOT / "artifacts"
if str(ROOT) not in sys.path: sys.path.insert(0, str(ROOT))
RAW_ARTIFACT = ARTIFACTS / "director-quality-v3-final-recanary-real.json"
ORIGINAL_COMMIT = "9db8f9f"
SCENES = ("book990402:e3:暗房惊魂", "book990402:e3:暗房惊魂（2）", "book990402:e2:回声照相馆")

def _d(v: Any) -> dict[str, Any]: return v if isinstance(v, dict) else {}
def _l(v: Any) -> list[Any]: return v if isinstance(v, list) else []
def _t(v: Any) -> str: return str(v or "").strip()
def _canon(v: Any) -> str: return json.dumps(v, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)
def _fp(v: Any) -> str: return hashlib.sha256(_canon(v).encode("utf-8")).hexdigest()
def _write(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True); path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
def _safe(value: str) -> str: return (re.sub(r"[^A-Za-z0-9]+", "-", value).strip("-").lower() or "scene") + "-" + _fp(value)[:10]

def _contract(inputs: dict[str, Any]) -> dict[str, Any]:
    from core.director_scene_strategy import build_runtime_strategy_contract
    return build_runtime_strategy_contract(scene=inputs["scene"], treatment=inputs["director_treatment"], blocking=inputs["scene_blocking"], fact_snapshot=inputs["fact_snapshot"])

def _records() -> list[dict[str, Any]]:
    from scripts.run_director_quality_v3_phase1_2 import _load_records, _authoritative
    rows = _load_records()
    if tuple(_t(_d(r.get("metadata")).get("scene_id")) for r in rows) != SCENES: raise RuntimeError("frozen scene order changed")
    return rows

def _equivalence(runtime: dict[str, Any], provider: dict[str, Any]) -> dict[str, Any]:
    source, rsource = _d(provider.get("source_ref_contract")), _d(runtime.get("source_ref_contract"))
    pa, ra = source.get("beat_alias_table"), runtime.get("beat_alias_table")
    pids, rids = provider.get("allowed_source_refs", []), runtime.get("allowed_source_refs", [])
    pbeats, rbeats = provider.get("allowed_beat_ids", []), runtime.get("beat_ids", [])
    pchars, rchars = provider.get("allowed_character_ids", []), sorted(runtime.get("character_ids", []))
    provider_projection = {"scene_id": provider.get("scene_id"), "allowed_beat_ids": pbeats, "allowed_character_ids": pchars, "source_ref_contract": source, "allowed_source_refs": pids}
    runtime_projection = {"scene_id": runtime.get("scene_id"), "allowed_beat_ids": rbeats, "allowed_character_ids": rchars, "source_ref_contract": rsource, "allowed_source_refs": rids}
    return {"scene_id": runtime.get("scene_id"), "provider_beat_ids": pbeats, "runtime_beat_ids": rbeats, "beat_ids_equal": pbeats == rbeats, "provider_character_ids": pchars, "runtime_character_ids": rchars, "character_ids_equal": pchars == rchars, "provider_allowed_source_refs": pids, "runtime_allowed_source_refs": rids, "allowed_source_refs_equal": pids == rids, "provider_beat_alias_table_fingerprint": _fp(pa), "runtime_beat_alias_table_fingerprint": _fp(ra), "beat_alias_equal": pa == ra, "provider_source_ref_contract_fingerprint": _fp(source), "runtime_source_ref_contract_fingerprint": _fp(rsource), "source_ref_contract_equal": source == rsource, "provider_visible_contract_fingerprint": _fp(provider_projection), "runtime_validation_contract_fingerprint": _fp(runtime_projection), "contract_fingerprint_equal": _fp(provider_projection) == _fp(runtime_projection)}

def _error_codes(errors: list[dict[str, Any]]) -> list[str]: return [_t(_d(e).get("code")) for e in errors if _t(_d(e).get("code"))]

def _brief(scene: dict[str, Any]) -> str:
    candidate = scene.get("canonical") or scene.get("normalized_ir") or {}
    lines = [f"# Director Brief — {_t(_d(scene.get('scene')).get('scene_id'))}", "", "Evidence Source: `ORIGINAL_MIMO_OUTPUT_FROM_9db8f9f`", "New LLM Calls: `0`", "Adjudication: `HARNESS_CORRECTION_REPLAY`", "", f"Protocol: `{'PROTOCOL_VALID' if scene.get('adjudicated_protocol_status') == 'PROTOCOL_VALID' else 'PROTOCOL_INVALID'}`", f"Signal: `{scene.get('directing_signal')}`", "", "## Dramatic Objective", "", _t(candidate.get("dramatic_objective")), "", "## Scene Question", "", _t(candidate.get("scene_question")), "", "## Visual Thesis", "", _t(candidate.get("visual_thesis")), "", "## Phases", ""]
    for phase in _l(candidate.get("scene_phases")):
        if not isinstance(phase, dict): continue
        info = _d(phase.get("information")); performance = "; ".join(f"{_t(_d(x).get('character_id'))}：{_t(_d(x).get('objective'))}" for x in _l(phase.get("performance")) if isinstance(x, dict))
        lines += [f"### {_t(phase.get('phase_id'))} · beats {', '.join(_t(x) for x in _l(phase.get('beat_ids')))}", "", f"- Audience / emotion / power: {_t(_d(phase.get('audience_state')).get('question_shift'))}；{_t(_d(phase.get('emotion')).get('state'))}；{_t(_d(phase.get('power')).get('description'))}", f"- Performance: {performance}", f"- Edit / visual: {_t(_d(phase.get('edit')).get('cut_logic'))}；{_t(_d(phase.get('visual')).get('camera_rule'))}", f"- [FACT] Reveals: {', '.join(_t(x) for x in _l(info.get('reveal_refs'))) or '无'}", f"- [SUSPICION] Audience: {'; '.join(_t(_d(x).get('claim')) for x in _l(info.get('audience_suspicions')) if isinstance(x, dict)) or '无'}", f"- [INFERENCE] Director: {'; '.join(_t(_d(x).get('claim')) for x in _l(info.get('director_inferences')) if isinstance(x, dict)) or '无'}", ""]
    lines += ["## Must Preserve / Avoid / Risks", "", "- Must Preserve: " + "；".join(_t(x) for x in _l(candidate.get("must_preserve"))), "- Must Avoid: " + "；".join(_t(x) for x in _l(candidate.get("must_avoid"))), "- Creative Risks: " + "；".join(_t(x) for x in _l(candidate.get("creative_risks"))), "", "> Adjudicated strategy evidence only. No ShotPlan, media or production task was created."]
    return "\n".join(line.rstrip() for line in lines) + "\n"

def run() -> dict[str, Any]:
    from core.director_scene_strategy_ir_normalizer import normalize_strategy_ir_v2
    from core.director_scene_strategy_ir_v2 import validate_strategy_ir_v2
    from core.director_scene_strategy_ir_compiler_v2 import compile_ir_v2_to_canonical_v3
    from core.director_strategy_prompt import build_scene_strategy_ir_v2_prompt
    from core.director_strategy_quality import diagnose_scene_strategy_v2, compare_canonical_strategies
    from core.structured_output import parse_json_object
    raw_doc = json.loads(RAW_ARTIFACT.read_text(encoding="utf-8")); records = _records(); equivalence=[]; runtime_contracts=[]; scenes=[]; raw_manifest=[]
    for original, record in zip(raw_doc.get("scenes", []), records):
        from scripts.run_director_quality_v3_phase1_2 import _authoritative
        inputs = _authoritative(record); runtime = _contract(inputs); prompt = build_scene_strategy_ir_v2_prompt(evidence={"scene_id": runtime["scene_id"], "strategy_contract": runtime, "source_authority": inputs["source_authority"], "baseline_shot_count": inputs["baseline_shot_plan_metadata"]["shot_count"]}, model_profile={"id":"local-llm-2vydoz","provider":"openai-compatible","model_name":"mimo-v2.5"})
        eq = _equivalence(runtime, prompt["provider_contract"]); equivalence.append(eq); runtime_contracts.append(runtime)
        attempt = _l(original.get("attempts"))[0] if _l(original.get("attempts")) else {}; raw = _t(attempt.get("raw_provider_output")); raw_hash = _fp(raw)
        parsed = parse_json_object(raw, label="director_scene_strategy_ir_v2")
